#pragma once
#include <QJsonDocument>
#include <QJsonObject>
#include <QJsonArray>
#include <QCryptographicHash>
#include <QSet>
#include <QStringList>
#include <QHash>
#include <cstring>
#include <cmath>
#include <stdexcept>
namespace personMethod {
inline void need(bool ok,const QString& why){if(!ok)throw std::runtime_error(why.toStdString());}
inline QByteArray json(const QJsonObject& r){return QJsonDocument(r).toJson(QJsonDocument::Compact);}
inline QByteArray canonical(const QJsonValue& v){if(v.isObject()){QByteArray s="{";auto o=v.toObject();for(auto k:o.keys()){if(s.size()>1)s+=',';s+=canonical(k)+':'+canonical(o[k]);}return s+'}';}if(v.isArray()){QByteArray s="[";for(auto item:v.toArray()){if(s.size()>1)s+=',';s+=canonical(item);}return s+']';}if(v.isDouble()){double n=v.toDouble()==0?0:v.toDouble();need(std::isfinite(n)&&std::abs(n)<=9007199254740991.0,"数值超出可移植精度，请用文本保留原值");quint64 bits;std::memcpy(&bits,&n,sizeof(bits));return '@'+QByteArray::number(bits,16).rightJustified(16,'0');}auto s=QJsonDocument(QJsonArray{v}).toJson(QJsonDocument::Compact);return s.mid(1,s.size()-2);}
inline QString hash(const QJsonValue& v){return QString::fromLatin1(QCryptographicHash::hash(canonical(v),QCryptographicHash::Sha256).toHex());}
inline QString opaque(const QJsonValue& v){return v.isString()?v.toString():v.isDouble()?QString::number(v.toDouble(),'g',16):QString();}
inline QString text(const QJsonObject& r,const QString& key,int max,bool required=false){auto v=r[key];need(v.isString(),key+"必须为文本");auto s=v.toString();need(s.size()<=max&&(!required||!s.trimmed().isEmpty()),key+"缺失或过长，未截断");return s;}
inline QJsonObject version(QString space,QString kind,QString id,const QJsonObject& record){need(!space.isEmpty()&&!kind.isEmpty()&&!id.isEmpty()&&opaque(record["id"])==id,"完整版本身份不匹配");return {{"namespace",space},{"kind",kind},{"id",id},{"fingerprint",hash(record)},{"originalRecord",record}};}
inline void validateVersion(const QJsonObject& r){need(r["originalRecord"].isObject(),"关联缺少完整原版本");auto expected=version(text(r,"namespace",100,true),text(r,"kind",100,true),text(r,"id",400,true),r["originalRecord"].toObject());need(canonical(expected)==canonical(r),"关联版本指纹或字段不匹配，未按名称猜测");}
inline QString body(const QJsonObject& r){QStringList parts;for(auto k:{"text","content","transcript"})if(r[k].isString()&&!r[k].toString().isEmpty())parts.append(r[k].toString());return parts.join("\n\n");}
inline QJsonObject assess(const QJsonObject& r){bool supplied=true;for(auto k:{"title","versionLabel","conditions","steps","evidenceQuote","counterexamples","invalidations"})supplied=supplied&&!r[k].toString().trimmed().isEmpty();bool matched=false;for(auto v:r["sourceRefs"].toArray())matched=matched||(!r["evidenceQuote"].toString().isEmpty()&&body(v.toObject()["originalRecord"].toObject()).contains(r["evidenceQuote"].toString()));return {{"status",supplied&&matched?"fields_complete_not_validated":"draft"},{"quoteMatched",matched},{"authorConfirmed",false},{"methodValidated",false}};}
inline QJsonObject validate(QJsonObject r){auto kind=text(r,"kind",30,true);need(QStringList{"subjects","sources","methods"}.contains(kind),"未知人物方法记录类型");text(r,"id",400,true);text(r,"entityId",200,true);text(r,"parentId",400);text(r,"savedAt",50);need(!r.contains("archived")||r["archived"].isBool(),"归档状态必须为布尔值");
 if(kind=="subjects"){need(QStringList{"creator","person","book","method"}.contains(text(r,"subjectType",30,true)),"对象类型无效");text(r,"displayName",160,true);text(r,"platform",60,true);auto url=text(r,"profileUrl",1200);need(url.isEmpty()||url.startsWith("https://")||url.startsWith("http://"),"出处链接仅支持HTTP/HTTPS");text(r,"description",10000);need(r["aliases"].isArray(),"别名必须为数组");for(auto v:r["aliases"].toArray())need(v.isString()&&v.toString().size()<=160,"别名无效");auto state=text(r,"identityStatus",30,true);need(QStringList{"unverified","manuallyReviewed"}.contains(state),"身份不支持自动确认");auto basis=text(r,"identityBasis",10000);need(state!="manuallyReviewed"||!basis.trimmed().isEmpty(),"人工身份记录需填写依据；不代表独立确认");}
 if(kind=="sources"){text(r,"subjectId",200,true);text(r,"title",300,true);text(r,"text",1700000);need(r["legacyOriginal"].isObject(),"旧来源原记录缺失");need(r["text"]==body(r["legacyOriginal"].toObject()),"来源文字与完整原记录不一致");}
 if(kind=="methods"){text(r,"subjectId",200,true);validateVersion(r["subjectRef"].toObject());auto subject=r["subjectRef"].toObject()["originalRecord"].toObject();need(r["subjectRef"].toObject()["namespace"]=="person-method"&&r["subjectRef"].toObject()["kind"]=="subjects"&&subject["entityId"]==r["subjectId"]&&subject["kind"]=="subjects","方法关联人物版本不匹配");validate(subject);text(r,"title",200,true);text(r,"versionLabel",160);for(auto k:{"conditions","steps","evidenceQuote","counterexamples","invalidations","interpretation"})text(r,k,50000);need(r["sourceRefs"].isArray()&&r["sourceRefs"].toArray().size()<=100,"关联版本数组无效");for(auto v:r["sourceRefs"].toArray())validateVersion(v.toObject());need(r["assessment"]==assess(r),"方法状态必须保持草稿/未验证，不能导入确认主张");}
 auto revision=r["recordRevision"].toString();need(!revision.isEmpty(),"记录缺少版本指纹");r.remove("recordRevision");need(revision==hash(r),"记录版本指纹不一致，未接受改写");r["recordRevision"]=revision;need(json(r).size()<=25*1024*1024,"单记录超过25MiB，未截断");return r;
}
inline QJsonObject seal(QJsonObject r){r.remove("recordRevision");if(r["kind"]=="methods")r["assessment"]=assess(r);r["recordRevision"]=hash(r);return validate(r);}
inline QJsonObject empty(){return {{"schema","person-method/v1"},{"subjects",QJsonArray{}},{"sources",QJsonArray{}},{"methods",QJsonArray{}}};}
inline QJsonObject legacy(const QJsonArray& channels){auto out=empty();QJsonArray subjects,sources;QSet<QString> seen;for(auto item:channels){need(item.isObject(),"旧对象必须为对象");const auto old=item.toObject();auto key=old["channelKey"].toString();need(!key.isEmpty()&&key.size()<=120&&!seen.contains(key),"旧对象缺少明确channelKey或重复，未按名称合并");seen.insert(key);auto entity="legacy-subject:"+key;auto metadata=old;metadata.remove("observations");QJsonObject s{{"kind","subjects"},{"entityId",entity},{"id",entity+"@"+hash(metadata)},{"parentId",""},{"savedAt",""},{"subjectType",old["subjectType"].toString("creator")},{"displayName",old["displayName"]},{"platform",old["platform"]},{"profileUrl",old["profileUrl"].toString()},{"description",old["description"].toString()},{"aliases",old.contains("aliases")?old["aliases"]:QJsonValue(QJsonArray{})},{"identityStatus","unverified"},{"identityBasis",""},{"legacyOriginal",metadata}};subjects.append(seal(s));need(!old.contains("observations")||old["observations"].isArray(),"旧observations不是数组");QSet<QString> ids;for(auto value:old["observations"].toArray()){need(value.isObject(),"旧资料必须为对象");const auto o=value.toObject();auto id=opaque(o["id"]);if(id.isEmpty())id=o["externalKey"].toString();need(!id.isEmpty()&&!ids.contains(id),"旧资料缺少明确身份或重复");ids.insert(id);auto sourceEntity="legacy-source:"+QString::fromLatin1(QCryptographicHash::hash((key+'\n'+id).toUtf8(),QCryptographicHash::Sha256).toHex());auto title=o["title"].toString();need(!title.trimmed().isEmpty(),"旧资料标题缺失");sources.append(seal({{"kind","sources"},{"entityId",sourceEntity},{"id",sourceEntity+"@"+hash(o)},{"parentId",""},{"savedAt",""},{"subjectId",entity},{"title",title},{"text",body(o)},{"legacyIdentity",QJsonObject{{"channelKey",key},{"observationId",id}}},{"legacyOriginal",o}}));}}out["subjects"]=subjects;out["sources"]=sources;return out;}
inline void depth(const QJsonValue& v,int level=0){need(level<=100,"JSON嵌套超过100层");if(v.isObject()){const auto o=v.toObject();for(auto it=o.begin();it!=o.end();++it)depth(it.value(),level+1);}else if(v.isArray())for(auto item:v.toArray())depth(item,level+1);}
inline QJsonObject decode(const QByteArray& input){need(input.size()<=32*1024*1024,"文件超过32MiB，请分批导出");QJsonParseError e;auto d=QJsonDocument::fromJson(input,&e);need(e.error==QJsonParseError::NoError&&d.isObject(),"导入JSON无效");auto r=d.object();depth(r);if(r.value("schema")!="person-method/v1"){need(!r.contains("schema"),"人物方法备份版本不支持，未降级导入");auto channels=r["expertChannels"];if(!channels.isArray())channels=r["tables"].toObject()["expertChannels"];need(channels.isArray(),"需要official tables.expertChannels或person-method备份");r=legacy(channels.toArray());}for(auto k:{"subjects","sources","methods"}){need(r[k].isArray()&&r[k].toArray().size()<=10000,"记录数组缺失或过多");QSet<QString> ids;for(auto v:r[k].toArray()){need(v.isObject()&&v.toObject()["kind"]==QString(k),"记录类别不匹配");auto row=validate(v.toObject());need(!ids.contains(row["id"].toString()),"同一文件重复版本ID");ids.insert(row["id"].toString());}}need(json(r).size()<=64*1024*1024,"转换后超过64MiB，请分批导出");return r;}
inline QJsonObject preview(const QJsonObject& incoming,const QJsonObject& current){auto inserts=empty();QJsonArray conflicts;int duplicate=0,added=0;for(auto k:{"subjects","sources","methods"}){QHash<QString,QJsonObject> existing;for(auto v:current[k].toArray())existing[v.toObject()["id"].toString()]=v.toObject();QJsonArray rows;for(auto v:incoming[k].toArray()){auto r=v.toObject(),old=existing.value(r["id"].toString());if(old.isEmpty()){rows.append(r);++added;}else if(canonical(old)==canonical(r))++duplicate;else conflicts.append(QString(k)+":"+r["id"].toString());}inserts[k]=rows;}return {{"inserts",inserts},{"added",added},{"duplicate",duplicate},{"conflicts",conflicts}};}
}
